python3 -c "
import json

with open('/app/resources/treasury_bulletin_2007_09.json', 'r') as f:
    data = json.load(f)

# Search for figure on page 12
for i, elem in enumerate(data['document']['elements']):
    bbox = elem.get('bbox', [])
    if bbox and len(bbox) > 0:
        for b in bbox:
            if b.get('page_id') == 12:
                print(f'Element {i}: type={elem.get(\"type\")}')
                content = elem.get('content')
                if content:
                    print(f'Content: {str(content)[:500]}')
                print('---')
"
